"""The Copilot v2 runtime's view of an agent's workspace, backed by git branches.

Implements `rasa.builder.copilot.pydantic_ai.workspace.CopilotWorkspace`, which
keeps the runtime free of any knowledge about how branches are checked out.
"""

from pathlib import Path

from rasa.builder.branches import create_branch
from rasa.builder.copilot.pydantic_ai.workspace import BranchOffError
from rasa.builder.exceptions import (
    BranchAlreadyExistsError,
    BranchNotFoundError,
    InvalidBranchNameError,
)
from rasa.builder.git_service import GitOperationInProgressError
from rasa.builder.project_generator import ProjectGenerator
from rasa.builder.workspace import Workspace, WorkspaceManager, validate_branch_name

# How many `name-2`, `name-3`, ... to try before giving up on a taken name.
MAX_BRANCH_NAME_ATTEMPTS = 100


class BranchingWorkspace:
    """The branch of an agent a Copilot run is on, which can branch off itself."""

    def __init__(self, workspace: Workspace, manager: WorkspaceManager) -> None:
        """Initialise the workspace.

        Args:
            workspace: The workspace the run starts on.
            manager: Manager of the agent's workspaces, to check out new branches.
        """
        self._workspace = workspace
        self._manager = manager

    @property
    def branch(self) -> str:
        """Name of the branch currently checked out."""
        return self._workspace.branch

    @property
    def path(self) -> Path:
        """Folder of the current branch's checkout."""
        return self._workspace.path

    @property
    def project_generator(self) -> ProjectGenerator:
        """The generator operating on the current branch's checkout."""
        return self._workspace.project_generator

    async def branch_off(self, name: str) -> str:
        """Create a branch from the current one and switch to it.

        If `name` is taken, `name-2`, `name-3`, ... is tried instead.

        Args:
            name: Wanted name of the new branch.

        Returns:
            The name of the branch created, which is now the current one.

        Raises:
            BranchOffError: If the name is invalid, no free name was found, or
                another git operation is running.
        """
        main = self._manager.get_or_create(self._workspace.agent_id)
        try:
            validate_branch_name(name)
            for attempt in range(1, MAX_BRANCH_NAME_ATTEMPTS + 1):
                candidate = name if attempt == 1 else f"{name}-{attempt}"
                try:
                    await create_branch(main, candidate, from_ref=self.branch)
                except BranchAlreadyExistsError:
                    continue
                self._workspace = self._manager.get_or_create(
                    self._workspace.agent_id, candidate
                )
                return candidate
        except (
            InvalidBranchNameError,
            BranchNotFoundError,
            GitOperationInProgressError,
        ) as exc:
            raise BranchOffError(str(exc)) from exc
        raise BranchOffError(
            f"No free branch name found starting from '{name}'; pick another name."
        )
